package kome.common.data;
import static org.junit.Assert.*;import java.util.UUID;import lotr.common.LOTRDimension;import lotr.common.fac.LOTRFaction;import lotr.common.world.map.LOTRWaypoint;import net.minecraft.init.Items;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;import org.junit.Test;
public class KOMESerfCourierAssignmentTest {
 private KOMEProgressionNpcRef master(){return new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Aldor","rohan",LOTRDimension.MIDDLE_EARTH.dimensionID,LOTRWaypoint.EDORAS.getXCoord()+800,64,LOTRWaypoint.EDORAS.getZCoord()+800);}
 @Test public void assignmentNeedsNoLoadedRecipientAndPersistsNativeDestination(){KOMEProgressionNpcRef m=master();KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(m,LOTRWaypoint.EDORAS);assertNotNull(a);assertFalse(a.recipient.isSet());KOMESerfCourierAssignment b=KOMESerfCourierAssignment.readFromNBT(a.writeToNBT());assertEquals(LOTRWaypoint.EDORAS.getCodeName(),b.destinationKey);assertEquals(LOTRWaypoint.EDORAS.getDisplayName(),b.destinationName);assertEquals(a.token,b.token);assertFalse(b.recipient.isSet());}
 @Test public void malformedPayloadFailsClosedAndOldAssignmentGetsDeterministicDestination(){KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(master(),LOTRWaypoint.EDORAS);NBTTagCompound bad=a.writeToNBT();bad.setString("RecipientRuleKey","cross_faction");assertNull(KOMESerfCourierAssignment.readFromNBT(bad));NBTTagCompound old=a.writeToNBT();old.setInteger("Version",1);old.removeTag("DestinationKey");old.removeTag("DestinationName");KOMESerfCourierAssignment migrated=KOMESerfCourierAssignment.readFromNBT(old);assertNotNull(migrated);assertTrue(migrated.destinationName.length()>0);assertEquals(a.token,migrated.token);}
 @Test public void recipientBindingAndDeliveryStageRoundTrip(){KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(master(),LOTRWaypoint.EDORAS);a.recipient=new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Recipient","rohan",a.dimension,a.destinationX,64,a.destinationZ);a.stage=KOMESerfCourierAssignment.Stage.DELIVERED;KOMESerfCourierAssignment b=KOMESerfCourierAssignment.readFromNBT(a.writeToNBT());assertEquals(KOMESerfCourierAssignment.Stage.DELIVERED,b.stage);assertTrue(b.recipient.hasSameIdentity(a.recipient));}
 @Test public void dispatchIsStableInWorldMessageAndKeepsAuthorityHidden(){KOMEProgressionNpcRef m=master();KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(m,LOTRWaypoint.EDORAS);UUID player=UUID.randomUUID();String first=KOMECourierService.message(a,player,m).getTagCompound().getTagList("pages",8).getStringTagAt(0);KOMESerfCourierAssignment loaded=KOMESerfCourierAssignment.readFromNBT(a.writeToNBT());ItemStack book=KOMECourierService.message(loaded,player,m);String page=book.getTagCompound().getTagList("pages",8).getStringTagAt(0);assertEquals(first,page);assertTrue(page.contains(a.destinationName));assertTrue(page.contains(m.displayName));assertTrue(page.length()>100);assertFalse(page.contains(a.token));assertFalse(page.contains("Courier Duty"));assertFalse(page.contains("objective"));assertEquals(a.token,book.getTagCompound().getCompoundTag("KOMECourier").getString("Assignment"));}
 @Test public void onlyCorrectTaggedDispatchAndOwnerMatch(){KOMEProgressionNpcRef m=master();KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(m,LOTRWaypoint.EDORAS);UUID owner=UUID.randomUUID();ItemStack dispatch=KOMECourierService.message(a,owner,m);assertTrue(KOMECourierService.matching(dispatch,a,owner,m));assertFalse(KOMECourierService.matching(dispatch,a,UUID.randomUUID(),m));assertFalse(KOMECourierService.matching(new ItemStack(Items.written_book),a,owner,m));KOMESerfCourierAssignment other=KOMESerfCourierAssignment.create(m,LOTRWaypoint.EDORAS);assertFalse(KOMECourierService.matching(dispatch,other,owner,m));}
 @Test public void destinationSelectionIsDeterministicAndDoesNotNeedWorldEntities(){KOMEProgressionNpcRef m=master();assertSame(KOMESerfCourierAssignment.chooseDestination(m),KOMESerfCourierAssignment.chooseDestination(m));assertNotNull(KOMESerfCourierAssignment.create(m));}
 @Test public void everyPlayableFactionCanSelectOwnOrNonHostileNativeDestination(){for(LOTRFaction faction:LOTRFaction.getPlayableAlignmentFactions()){KOMEProgressionNpcRef m=new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Master",faction.codeName(),LOTRDimension.MIDDLE_EARTH.dimensionID,0,64,0);KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(m);assertNotNull("No Courier destination for "+faction.codeName(),a);LOTRFaction destination=LOTRFaction.forName(a.destinationFactionKey);assertNotNull(destination);assertTrue(destination==faction||(!faction.isBadRelation(destination)&&!destination.isBadRelation(faction)));}}
 @Test public void recipientDeathClearsBindingForSameDestinationRetry(){KOMEWorldData world=new KOMEWorldData("courier-death");UUID player=UUID.randomUUID();KOMEPlayerProgression progression=world.getProgression(player);progression.setCanonicalRank(KOMEProgressionRank.SERF);KOMEProgressionNpcRef m=master(),r=new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Recipient","rohan",LOTRDimension.MIDDLE_EARTH.dimensionID,LOTRWaypoint.EDORAS.getXCoord(),64,LOTRWaypoint.EDORAS.getZCoord());assertTrue(KOMESerfKnightService.setSerfdomMaster(progression.getSerfKnightProgression(),m).success);KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(m,LOTRWaypoint.EDORAS);a.recipient=r;assertTrue(KOMESerfKnightService.assignDuty(progression.getSerfKnightProgression(),KOMESerfKnightDutyType.COURIER,a.writeToNBT(),10L).success);KOMEProgressionNpcRoles.syncPlayer(world,player);assertTrue(KOMEProgressionNpcRoles.protects(world,UUID.fromString(r.entityUuid)));assertTrue(KOMECourierService.handleRecipientDeath(world,r.entityUuid));KOMESerfCourierAssignment restored=KOMESerfCourierAssignment.readFromNBT(progression.getSerfKnightProgression().getDuty(KOMESerfKnightDutyType.COURIER).getAssignmentData());assertFalse(restored.recipient.isSet());assertEquals(a.destinationKey,restored.destinationKey);assertEquals(a.token,restored.token);assertEquals(1,restored.recipientDeaths);assertEquals(1200L,restored.nextRecipientWorldTime);assertFalse(KOMEProgressionNpcRoles.protects(world,UUID.fromString(r.entityUuid)));}
 @Test public void replacementDelayAndDestinationPersistWithoutReroute(){KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(master(),LOTRWaypoint.EDORAS);a.recipientDeaths=2;a.nextRecipientWorldTime=4800L;KOMESerfCourierAssignment b=KOMESerfCourierAssignment.readFromNBT(a.writeToNBT());assertEquals(a.token,b.token);assertEquals(a.destinationKey,b.destinationKey);assertEquals(2,b.recipientDeaths);assertEquals(4800L,b.nextRecipientWorldTime);assertEquals(1200L,KOMECourierService.replacementDelay(1));assertEquals(6000L,KOMECourierService.replacementDelay(99));}
 @Test public void oldUndeliverableSaveResumesAtSameDestination(){KOMESerfCourierAssignment a=KOMESerfCourierAssignment.create(master(),LOTRWaypoint.EDORAS);NBTTagCompound old=a.writeToNBT();old.setInteger("Version",5);old.setString("Stage","undeliverable");KOMESerfCourierAssignment loaded=KOMESerfCourierAssignment.readFromNBT(old);assertEquals(KOMESerfCourierAssignment.Stage.OUTBOUND,loaded.stage);assertEquals(a.token,loaded.token);assertEquals(a.destinationKey,loaded.destinationKey);}
 @Test public void dispatchVariantsUseFactionLanguageAndRecipientName(){KOMEProgressionNpcRef m=master();KOMESerfCourierAssignment rohan=KOMESerfCourierAssignment.create(m,LOTRWaypoint.EDORAS);rohan.storyVariant=0;assertTrue(KOMECourierService.dispatchText(rohan,m).contains("Riders"));KOMESerfCourierAssignment gondor=KOMESerfCourierAssignment.create(m,LOTRWaypoint.MINAS_TIRITH);gondor.storyVariant=4;assertTrue(KOMECourierService.dispatchText(gondor,m).contains("records"));KOMESerfCourierAssignment mordor=KOMESerfCourierAssignment.create(m,LOTRWaypoint.BARAD_DUR);mordor.storyVariant=2;assertTrue(KOMECourierService.dispatchText(mordor,m).contains("Delay will not be forgiven"));mordor.recipient=new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Gorbag",mordor.destinationFactionKey,mordor.dimension,mordor.destinationX,64,mordor.destinationZ);assertTrue(KOMECourierService.dispatchText(mordor,m).startsWith("Gorbag,"));}
}
